<script setup>
import { tr, getLocale } from '../../utils/i18n'
import { computed, onUnmounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, Refresh, Search } from '@element-plus/icons-vue'
import { operateMiddleware } from '../../api/middleware'
import { getUser, getPermissions } from '../../utils/auth'
import { formatKafkaCount as count, kafkaOffsetAtLeast, kafkaOffsetPercent, kafkaPayload, kafkaConfigSource, kafkaMessageId } from './kafka-topic'
import KafkaMessagePanel from './KafkaMessagePanel.vue'
const props = defineProps({ sourceId: Number, topic: String })
const router = useRouter(), tab = ref('overview'), overview = ref(null), configs = ref([]), messages = ref(null), consumers = ref(null)
const baseLoading = ref(false), configLoading = ref(false), messagesLoading = ref(false), consumersLoading = ref(false), saving = ref(false)
const errors = reactive({ base:'', configs:'', messages:'', consumers:'' }), revision = ref(0)
const query = reactive({ partition:'0', mode:'latest', offset:'0', timestamp:'', limit:'50' })
const messageFilter = ref(''), configFilter = ref(''), groupFilter = ref(''), consumerDetail = ref(null)
const messageTable = ref(null)
const produceDialog = ref(false), configDialog = ref(false), partitionsDialog = ref(false), configEdit = reactive({})
const production = reactive({ partition:'0', key:'', value:'', nullKey:true, tombstone:false, keyEncoding:'utf8', valueEncoding:'utf8', headers:'[]' })
const newPartitions = ref(1), cursorHistory = ref([]), messageScope = ref(null), confirming = ref(false), clearing = ref(false), expandedKeys = ref([])
let generation = 0, baseRequest = 0, messageRequest = 0, consumerRequest = 0
const can = action => { revision.value; return getUser().accountType === 'administrator' || getPermissions().includes(`assets:middleware:${action}`) }
const partitions = computed(() => overview.value?.partitions || [])
const replication = computed(() => [...new Set(partitions.value.map(p => p.replicas.length))].join(' / ') || '—')
const cleanup = computed(() => configs.value.find(c => c.name === 'cleanup.policy')?.value || '—')
const visibleMessages = computed(() => (messages.value?.items || []).filter(m => `${m.key.text} ${m.value.text} ${m.offset}`.toLowerCase().includes(messageFilter.value.toLowerCase())))
const visibleConfigs = computed(() => configs.value.filter(c => `${c.name} ${c.value}`.toLowerCase().includes(configFilter.value.toLowerCase())))
const maxSpan = computed(() => partitions.value.reduce((max,p) => kafkaOffsetAtLeast(p.offsetSpan,max) ? p.offsetSpan : max,'0'))
const brokerStats = computed(() => { const stats = new Map(); for (const p of partitions.value) { for (const id of p.replicas) { if (!stats.has(id)) stats.set(id,{ id, leaders:0, replicas:0, isr:0 }); const b = stats.get(id); b.replicas++; if (p.leader === id) b.leaders++; if (p.isr.includes(id)) b.isr++ } }; return [...stats.values()].sort((a,b) => a.id-b.id) })
function valid() { return Number.isSafeInteger(props.sourceId) && props.sourceId > 0 && Boolean(props.topic) }
function api(operation, params = {}, action = 'query') { return operateMiddleware(props.sourceId,operation,{...params,name:props.topic},action,action !== 'query',operation === 'topic.clear' ? 60000 : 20000) }
function invalidateRequests() {
 generation++; baseRequest++; messageRequest++; consumerRequest++
 baseLoading.value=false; configLoading.value=false; messagesLoading.value=false; consumersLoading.value=false
 if(confirming.value) ElMessageBox.close()
 confirming.value=false; saving.value=false; clearing.value=false
}
function clearResults() {
 overview.value=null; configs.value=[]; messages.value=null; consumers.value=null; consumerDetail.value=null
 messageScope.value=null; cursorHistory.value=[]; expandedKeys.value=[]
 produceDialog.value=false; configDialog.value=false; partitionsDialog.value=false
 Object.keys(errors).forEach(k=>errors[k]='')
}
function reset() {
 invalidateRequests(); clearResults(); tab.value='overview'
 messageFilter.value=''; configFilter.value=''; groupFilter.value=''
 Object.assign(query,{partition:'0',mode:'latest',offset:'0',timestamp:'',limit:'50'})
 loadBase()
}
watch(() => [props.sourceId,props.topic],reset,{immediate:true})
function permissionsChanged() { revision.value++; invalidateRequests(); clearResults(); loadBase(); if (tab.value === 'messages') loadMessages(); if (tab.value === 'consumers') loadConsumers() }
window.addEventListener('ops-admin-permissions-changed',permissionsChanged)
onUnmounted(()=>{invalidateRequests();window.removeEventListener('ops-admin-permissions-changed',permissionsChanged)})
async function loadBase() { const g=generation,r=++baseRequest; if (!valid() || !can('query')) { baseLoading.value=false;configLoading.value=false;errors.base = valid() ? tr("当前没有查询该数据源的权限。") : tr("Topic 地址参数不正确。"); return }; baseLoading.value=true; configLoading.value=true; const results = await Promise.allSettled([api('topic.overview'),api('topic.configs')]); if(g!==generation||r!==baseRequest)return; baseLoading.value=false;configLoading.value=false; const [a,b]=results;overview.value=a.status==='fulfilled'?a.value:null;errors.base=a.status==='rejected'?a.reason.message:'';configs.value=b.status==='fulfilled'?b.value:[];errors.configs=b.status==='rejected'?b.reason.message:'' }
async function loadMessages(cursor) { if(!valid() || !can('query'))return; const g=generation,r=++messageRequest;messagesLoading.value=true;errors.messages='';expandedKeys.value=[]; const params={...(cursor!==undefined && messageScope.value ? messageScope.value : query)};if(cursor!==undefined){params.mode='offset';params.offset=cursor}; if(params.mode==='time'){const d=new Date(params.timestamp);if(Number.isNaN(d.getTime())){ElMessage.warning(tr("请选择有效时间"));messagesLoading.value=false;return};params.timestamp=d.toISOString()};try{const data=await api('topic.messages',params);if(g===generation&&r===messageRequest){messages.value=data;messageScope.value={...params}}}catch(e){if(g===generation&&r===messageRequest){errors.messages=e.message;messages.value=null}}finally{if(g===generation&&r===messageRequest)messagesLoading.value=false} }
function searchMessages(){cursorHistory.value=[];loadMessages()}
function nextMessages(){if(!messages.value?.hasMore)return;cursorHistory.value.push(messages.value.items?.[0]?.offset || query.offset);loadMessages(messages.value.nextOffset)}
function previousMessages(){const cursor=cursorHistory.value.pop();if(cursor!==undefined)loadMessages(cursor)}
async function loadConsumers(append=false){if(!valid() || !can('query'))return;const g=generation,r=++consumerRequest;consumersLoading.value=true;errors.consumers='';try{const data=await api('topic.consumers',{groupFilter:groupFilter.value,scanOffset:String(append?consumers.value?.nextScanOffset||0:0)});if(g===generation&&r===consumerRequest)consumers.value=append?{...data,items:[...(consumers.value?.items||[]),...data.items],warnings:[...(consumers.value?.warnings||[]),...data.warnings]}:data}catch(e){if(g===generation&&r===consumerRequest){errors.consumers=e.message;if(!append)consumers.value=null}}finally{if(g===generation&&r===consumerRequest)consumersLoading.value=false}}
function changeTab(){if(tab.value==='messages'&&!messages.value)loadMessages();if(tab.value==='consumers'&&!consumers.value)loadConsumers()}
function refresh(){if(tab.value==='messages')searchMessages();else if(tab.value==='consumers')loadConsumers();else loadBase()}
function back(){router.push({path:'/assets/middleware/kafka',query:{sourceId:props.sourceId}})}
async function confirm(label,description,confirmText=tr("确认执行")){if(confirming.value||saving.value||clearing.value)return false;const g=generation;confirming.value=true;try{await ElMessageBox.confirm(description,`${label} · ${props.topic}`,{type:'warning',confirmButtonText:confirmText,cancelButtonText:tr("取消")});return g===generation}catch{return false}finally{if(g===generation)confirming.value=false}}
function openProduce(){Object.assign(production,{partition:String(partitions.value[0]?.id??0),key:'',value:'',nullKey:true,tombstone:false,keyEncoding:'utf8',valueEncoding:'utf8',headers:'[]'});produceDialog.value=true}
async function produce(){try{const h=JSON.parse(production.headers||'[]');if(!Array.isArray(h))throw new Error()}catch{ElMessage.warning(tr("Headers 需要填写 JSON 数组"));return};if(!await confirm(tr("发送消息"),tr("向分区 {p0} 发送{p1}？", { p0: (production.partition), p1: (production.tombstone?' Tombstone':tr("一条消息")) })))return;const g=generation;saving.value=true;try{const data=await api('topic.produce',Object.fromEntries(Object.entries(production).map(([k,v])=>[k,String(v)])),'write');if(g!==generation)return;produceDialog.value=false;ElMessage.success(tr("发送成功：分区 {p0}，Offset {p1}", { p0: (data.partition), p1: (data.offset) }));messages.value=null;await loadBase()}finally{if(g===generation)saving.value=false}}
function editConfig(c){Object.assign(configEdit,c);configDialog.value=true}
async function updateConfig(reset=false){if(!await confirm(reset?tr("恢复默认配置"):tr("修改配置"),reset?tr("移除 Topic 的 {p0} 覆盖值，恢复继承 Broker / 默认配置？", { p0: (configEdit.name) }):tr("将 {p0} 修改为 {p1}？", { p0: (configEdit.name), p1: (configEdit.value) })))return;const g=generation;saving.value=true;try{await api('topic.config.set',{key:configEdit.name,value:configEdit.value,reset:String(reset)},'write');if(g!==generation)return;configDialog.value=false;ElMessage.success(tr("配置已更新"));await loadBase()}finally{if(g===generation)saving.value=false}}
async function increasePartitions(){if(!await confirm(tr("增加分区"),tr("将分区总数从 {p0} 增至 {p1}？分区不能减少，按 Key 路由的消息分配可能改变。", { p0: (partitions.value.length), p1: (newPartitions.value) })))return;const g=generation;saving.value=true;try{await api('topic.partitions',{partitions:String(newPartitions.value)},'write');if(g!==generation)return;partitionsDialog.value=false;ElMessage.success(tr("分区扩容请求已完成"));await loadBase()}finally{if(g===generation)saving.value=false}}
function viewPartition(p){query.partition=String(p.id);query.mode='earliest';cursorHistory.value=[];tab.value='messages';loadMessages()}
// 单击整行展开/收起消息内容；展开后整行高亮，行尾「查看 / 收起」给出明确入口。
const isExpanded = row => expandedKeys.value.includes(kafkaMessageId(row))
function toggleRow(row){messageTable.value?.toggleRowExpansion(row)}
function onRowClick(row, column, event){if(event?.target?.closest?.('button, a, input, .el-table__expand-icon'))return;toggleRow(row)}
function onExpandChange(row, rows){
  const id = kafkaMessageId(row)
  if (Array.isArray(rows)) expandedKeys.value = rows.map(kafkaMessageId)
  else expandedKeys.value = rows ? [...new Set([...expandedKeys.value, id])] : expandedKeys.value.filter(key => key !== id)
}
const rowClass = ({ row }) => isExpanded(row) ? 'msg-row-expanded' : ''
// Kafka 没有原地清空接口：后端会删除 Topic 后按原分区数与副本因子重建，并尽力恢复配置。
async function clearMessages(){
  if(clearing.value)return
  const shape = tr("共 {p0} 个分区，Offset 跨度 {p1}", { p0: (partitions.value.length), p1: (count(overview.value?.offsetSpan ?? '0')) })
  if(!await confirm(tr("清空消息"),tr("将删除 {p0} 的全部消息（{p1}）。执行时会先删除该 Topic，再按原分区数与副本因子重建，并尽力恢复 Topic 级配置。期间生产与消费会短暂中断，消费组已提交位点失效，消息不可恢复。", { p0: (props.topic), p1: (shape) }),tr("清空消息")))return
  const g=generation
  clearing.value=true
  try{
    const data=await api('topic.clear',{},'delete')
    if(g!==generation)return
    messages.value=null;messageScope.value=null;cursorHistory.value=[];expandedKeys.value=[]
    if(data?.warnings?.length)ElMessage.warning(tr("已清空，但 {p0} 项配置未能恢复：{p1}", { p0: (data.warnings.length), p1: (data.warnings[0]) }))
    else ElMessage.success(tr("已清空 {p0}，按 {p1} 个分区重建", { p0: (props.topic), p1: (data?.partitions ?? partitions.value.length) }))
    await loadBase()
  }catch(e){
    if(g===generation)ElMessage.error(e.message||tr("清空失败"))
  }finally{
    if(g===generation)clearing.value=false
  }
}
const displayTime = v => v && !v.startsWith('0001-') ? new Date(v).toLocaleString(getLocale()) : '—'
</script>
<template>
 <section class="topic-page">
  <header class="topic-header"><div class="topic-path"><el-button link type="primary" :icon="ArrowLeft" @click="back">Topics</el-button><span>/</span><h1>{{ topic }}</h1><el-tag v-if="overview" size="small" effect="plain" type="info">{{ overview.internal ? tr("内部 Topic") : tr("业务 Topic") }}</el-tag></div><div class="header-actions"><el-button :icon="Refresh" :loading="baseLoading" @click="refresh">{{ tr("刷新") }}</el-button><el-button v-if="can('write')" type="primary" :disabled="!overview" @click="openProduce">{{ tr("发送消息") }}</el-button><el-button v-if="can('delete')" type="danger" plain :disabled="!overview" :loading="clearing" @click="clearMessages">{{ tr("清空消息") }}</el-button></div></header>
  <el-alert v-if="errors.base" :title="errors.base" type="error" :closable="false" show-icon/>
  <el-tabs v-model="tab" class="topic-tabs" @tab-change="changeTab"><el-tab-pane :label="tr('概览')" name="overview"/><el-tab-pane :label="tr('消息')" name="messages"/><el-tab-pane :label="tr('消费者')" name="consumers"/><el-tab-pane :label="tr('配置')" name="settings"/><el-tab-pane :label="tr('统计')" name="statistics"/></el-tabs>
  <template v-if="tab === 'overview' || tab === 'statistics'">
   <div v-loading="baseLoading" class="topic-metrics"><div><span>{{ tr("分区数") }}</span><strong>{{ overview ? partitions.length : '—' }}</strong></div><div><span>{{ tr("副本因子") }}</span><strong>{{ replication }}</strong></div><div><span>{{ tr("副本不足分区 · URP") }}</span><strong :class="{'danger':overview?.underReplicated}">{{ overview?.underReplicated ?? '—' }}</strong></div><div><span>{{ tr("同步副本 · ISR") }}</span><strong>{{ overview ? `${overview.isrCount} / ${overview.replicaCount}` : '—' }}</strong></div><div><span>{{ tr("清理策略") }}</span><strong>{{ cleanup }}</strong></div><div><span>{{ tr("Offset 跨度") }}</span><strong>{{ count(overview?.offsetSpan) }}</strong></div></div>
   <p class="topic-note">{{ tr("Offset 跨度 = Next Offset − First Offset；压缩、事务和删除可能形成空洞，不代表精确消息条数。{p0}", { p0: (overview ? tr("采样时间：{p0}", { p0: (displayTime(overview.fetchedAt)) }) : '') }) }}</p>
   <template v-if="tab==='overview'"><div class="table-heading"><h2>{{ tr("分区") }}</h2><el-button v-if="can('write')" :disabled="!overview" @click="newPartitions=partitions.length+1;partitionsDialog=true">{{ tr("增加分区") }}</el-button></div><el-table :data="partitions" v-loading="baseLoading" row-key="id" :empty-text="tr('暂无分区数据')"><el-table-column prop="id" label="Partition ID" width="115"/><el-table-column prop="leader" label="Leader" width="100"/><el-table-column label="Replicas" min-width="120"><template #default="{row}">{{ row.replicas.join(', ') || '—' }}</template></el-table-column><el-table-column label="ISR" min-width="110"><template #default="{row}"><span :class="{'danger':row.isr.length<row.replicas.length}">{{ row.isr.join(', ') || '—' }}</span></template></el-table-column><el-table-column prop="firstOffset" label="First Offset" min-width="140"/><el-table-column prop="nextOffset" label="Next Offset" min-width="140"/><el-table-column :label="tr('Offset 跨度')" min-width="140"><template #default="{row}">{{count(row.offsetSpan)}}</template></el-table-column><el-table-column :label="tr('操作')" width="120" fixed="right"><template #default="{row}"><el-tooltip v-if="row.error" :content="row.error"><span class="danger">{{ tr("读取异常") }}</span></el-tooltip><el-button v-else link type="primary" @click="viewPartition(row)">{{ tr("浏览消息") }}</el-button></template></el-table-column></el-table></template>
   <template v-else><div class="table-heading"><h2>{{ tr("分区 Offset 分布") }}</h2></div><el-table :data="partitions"><el-table-column prop="id" :label="tr('分区')" width="100"/><el-table-column :label="tr('Offset 跨度')" width="180"><template #default="{row}">{{ count(row.offsetSpan) }}</template></el-table-column><el-table-column :label="tr('分布')"><template #default="{row}"><el-progress :percentage="kafkaOffsetPercent(row.offsetSpan,maxSpan)" :show-text="false" :stroke-width="10"/></template></el-table-column><el-table-column :label="tr('同步状态')" width="160"><template #default="{row}">{{ row.isr.length }} / {{ row.replicas.length }}</template></el-table-column></el-table><div class="table-heading"><h2>{{ tr("Broker 副本分布") }}</h2></div><el-table :data="brokerStats"><el-table-column prop="id" label="Broker ID"/><el-table-column prop="leaders" :label="tr('Leader 分区数')"/><el-table-column prop="replicas" :label="tr('副本数')"/><el-table-column prop="isr" :label="tr('同步副本数')"/></el-table><p class="topic-note">{{ tr("当前统计来自 Kafka 元数据与 Offset。日志段大小、磁盘占用及吞吐量需接入 Broker 监控后提供。") }}</p></template>
  </template>
  <template v-else-if="tab==='messages'">
   <div class="message-query"><label>{{ tr("分区") }}<el-select v-model="query.partition" :aria-label="tr('消息分区')"><el-option v-for="p in partitions" :key="p.id" :label="`Partition ${p.id}`" :value="String(p.id)"/></el-select></label><label>{{ tr("定位方式") }}<el-select v-model="query.mode" :aria-label="tr('消息定位方式')"><el-option :label="tr('最新消息')" value="latest"/><el-option :label="tr('最早消息')" value="earliest"/><el-option :label="tr('指定 Offset')" value="offset"/><el-option :label="tr('指定时间')" value="time"/></el-select></label><label v-if="query.mode==='offset'">Offset<el-input v-model="query.offset" :placeholder="tr('非负整数')" :aria-label="tr('消息 Offset')"/></label><label v-if="query.mode==='time'">{{ tr("时间") }}<el-date-picker v-model="query.timestamp" type="datetime" :placeholder="tr('定位时间')"/></label><label>{{ tr("条数") }}<el-select v-model="query.limit" :aria-label="tr('消息条数')"><el-option v-for="n in [20,50,100,200]" :key="n" :label="String(n)" :value="String(n)"/></el-select></label><el-button type="primary" :loading="messagesLoading" @click="searchMessages">{{ tr("查询") }}</el-button></div>
   <el-alert v-if="errors.messages" :title="errors.messages" type="error" :closable="false" show-icon/><div class="message-filter"><el-input v-model="messageFilter" :prefix-icon="Search" clearable :placeholder="tr('筛选本页 Key、Value 或 Offset')" :aria-label="tr('筛选当前页消息')"/><span>{{ tr("点击消息行或行尾「查看」展开 Key / Value / Headers · 直接读取分区，不提交业务消费位点") }}</span></div>
   <el-table ref="messageTable" :data="visibleMessages" :row-key="kafkaMessageId" v-loading="messagesLoading" :empty-text="tr('当前位置暂无可展示的消息')" class="message-table" :row-class-name="rowClass" @row-click="onRowClick" @expand-change="onExpandChange"><el-table-column type="expand" width="52"><template #default="{row}"><KafkaMessagePanel :message="row" @collapse="toggleRow(row)"/></template></el-table-column><el-table-column prop="offset" label="Offset" width="155"/><el-table-column prop="partition" :label="tr('分区')" width="80"/><el-table-column :label="tr('时间')" min-width="180"><template #default="{row}">{{displayTime(row.timestamp)}}</template></el-table-column><el-table-column label="Key" min-width="150" show-overflow-tooltip><template #default="{row}">{{kafkaPayload(row.key)}}</template></el-table-column><el-table-column label="Value" min-width="300" show-overflow-tooltip><template #default="{row}"><el-tag v-if="row.value.null" size="small" type="info">Tombstone</el-tag><span v-else>{{kafkaPayload(row.value)}}</span></template></el-table-column><el-table-column :label="tr('操作')" width="88" align="right" class-name="msg-view-cell"><template #default="{row}"><el-button link :type="isExpanded(row) ? 'info' : 'primary'" @click.stop="toggleRow(row)">{{ isExpanded(row) ? tr("收起") : tr("查看") }}</el-button></template></el-table-column></el-table>
   <footer class="topic-pagination"><span>{{ tr("{p0} 条{p1}结果 · 下一 Offset {p2}", { p0: (visibleMessages.length), p1: (messageFilter ? tr("匹配") : ''), p2: (messages?.nextOffset ?? '—') }) }}</span><el-button :disabled="!cursorHistory.length || messagesLoading" @click="previousMessages">{{ tr("上一页") }}</el-button><el-button :disabled="!messages?.hasMore || messagesLoading" @click="nextMessages">{{ tr("下一页") }}</el-button></footer><p class="topic-note">{{ tr("按分区 Offset 升序读取；单页最多 200 条、4 MiB，单条最多 1 MiB。二进制内容以 Base64 展示。{p0}", { p0: (messages?.truncated?tr("本页达到大小限制，可继续下一页。"):'') }) }}</p>
  </template>
  <template v-else-if="tab==='consumers'"><div class="message-filter"><el-input v-model="groupFilter" :prefix-icon="Search" clearable :placeholder="tr('按消费组名称筛选')" :aria-label="tr('消费组名称')" @keyup.enter="loadConsumers()"/><el-button type="primary" :loading="consumersLoading" @click="loadConsumers()">{{ tr("查询") }}</el-button></div><el-alert v-if="errors.consumers" :title="errors.consumers" type="error" :closable="false"/><el-alert v-if="consumers?.warnings?.length" :title="tr('有 {p0} 个消费组未能完整读取，结果可能不完整', { p0: (consumers.warnings.length) })" type="warning" :closable="false"><details><summary>{{ tr("查看原因") }}</summary><p v-for="warning in consumers.warnings" :key="warning">{{warning}}</p></details></el-alert><el-table :data="consumers?.items || []" v-loading="consumersLoading" :empty-text="tr('暂无关联消费组')"><el-table-column prop="groupId" :label="tr('消费组')" min-width="230"/><el-table-column prop="members" :label="tr('活跃消费者')" width="130"/><el-table-column label="Lag" min-width="150"><template #default="{row}">{{count(row.lag)}}</template></el-table-column><el-table-column prop="coordinator" label="Coordinator" width="140"/><el-table-column prop="state" :label="tr('状态')" width="160"/><el-table-column :label="tr('操作')" width="100"><template #default="{row}"><el-button link type="primary" @click="consumerDetail=row">{{ tr("详情") }}</el-button></template></el-table-column></el-table><footer class="topic-pagination"><span>{{ tr("已检查 {p0} / {p1} 个消费组；关联 {p2} 个", { p0: (consumers?.scanned || 0), p1: (consumers?.totalGroups || 0), p2: (consumers?.items?.length || 0) }) }}</span><el-button v-if="consumers?.hasMore" :loading="consumersLoading" @click="loadConsumers(true)">{{ tr("继续检查") }}</el-button></footer><p class="topic-note">{{ tr("Lag 按已提交 Offset 与分区末尾 Offset 计算；未提交位点的分区显示“—”。每批检查 100 个消费组。") }}</p></template>
  <template v-else-if="tab==='settings'"><el-alert v-if="errors.configs" :title="errors.configs" type="error" :closable="false"/><div class="message-filter"><el-input v-model="configFilter" :prefix-icon="Search" clearable :placeholder="tr('筛选配置项或值')" :aria-label="tr('筛选 Topic 配置')"/></div><el-table :data="visibleConfigs" v-loading="configLoading" :empty-text="tr('暂无可读取的配置')"><el-table-column prop="name" :label="tr('配置项')" min-width="260"/><el-table-column :label="tr('值')" min-width="220" show-overflow-tooltip><template #default="{row}">{{row.sensitive?'••••••':row.value || '—'}}</template></el-table-column><el-table-column :label="tr('来源')" width="175"><template #default="{row}">{{tr(kafkaConfigSource(row.source))}}</template></el-table-column><el-table-column :label="tr('状态')" width="100"><template #default="{row}">{{row.readOnly?tr("只读"):tr("可修改")}}</template></el-table-column><el-table-column v-if="can('write')" :label="tr('操作')" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="row.readOnly || row.sensitive" @click="editConfig(row)">{{ tr("编辑") }}</el-button></template></el-table-column></el-table></template>
  <el-dialog :model-value="Boolean(consumerDetail)" :title="consumerDetail?.groupId || tr('消费组详情')" width="min(900px,94vw)" class="kafka-topic-dialog" @close="consumerDetail=null"><template v-if="consumerDetail"><el-table :data="consumerDetail.partitions"><el-table-column prop="id" :label="tr('分区')"/><el-table-column prop="committedOffset" :label="tr('已提交 Offset')"/><el-table-column prop="endOffset" :label="tr('末尾 Offset')"/><el-table-column prop="lag" label="Lag"/><el-table-column prop="error" :label="tr('错误')" show-overflow-tooltip/></el-table><h4>{{ tr("关联客户端") }}</h4><el-table :data="consumerDetail.clients"><el-table-column prop="clientId" label="Client ID"/><el-table-column prop="host" :label="tr('客户端')"/><el-table-column prop="memberId" label="Member ID" show-overflow-tooltip/></el-table></template></el-dialog>
  <el-dialog v-model="produceDialog" :title="tr('发送消息')" width="min(720px,94vw)" class="kafka-topic-dialog" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><p class="topic-note">{{ tr("目标 Topic：{p0}", { p0: (topic) }) }}</p><el-form label-position="top" :disabled="saving"><el-form-item :label="tr('分区')"><el-select v-model="production.partition"><el-option v-for="p in partitions" :key="p.id" :label="`Partition ${p.id}`" :value="String(p.id)"/></el-select></el-form-item><div class="payload-heading"><h4>Key</h4><el-checkbox v-model="production.nullKey">{{ tr("无 Key（null）") }}</el-checkbox></div><el-form-item v-if="!production.nullKey"><el-select v-model="production.keyEncoding"><el-option label="UTF-8" value="utf8"/><el-option label="Base64" value="base64"/></el-select><el-input v-model="production.key" placeholder="Key"/></el-form-item><div class="payload-heading"><h4>Value</h4><el-checkbox v-model="production.tombstone">Tombstone（null Value）</el-checkbox></div><el-form-item v-if="!production.tombstone"><el-select v-model="production.valueEncoding"><el-option label="UTF-8 / JSON" value="utf8"/><el-option label="Base64" value="base64"/></el-select><el-input v-model="production.value" type="textarea" :rows="7" :placeholder="tr('消息内容')"/></el-form-item><el-form-item :label="tr('Headers（JSON 数组，可选）')"><el-input v-model="production.headers" type="textarea" :rows="2" placeholder='[{"key":"trace-id","value":"123"}]'/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="produceDialog=false">{{ tr("取消") }}</el-button><el-button type="primary" :loading="saving" @click="produce">{{ tr("发送") }}</el-button></template></el-dialog>
  <el-dialog v-model="configDialog" :title="tr('修改 Topic 配置')" width="min(600px,94vw)" class="kafka-topic-dialog" :close-on-click-modal="false"><el-form label-position="top" :disabled="saving"><el-form-item :label="tr('配置项')"><el-input :model-value="configEdit.name" disabled/></el-form-item><el-form-item :label="tr('值')"><el-input v-model="configEdit.value" type="textarea" :rows="3"/></el-form-item><p class="topic-note">{{configEdit.documentation}}</p></el-form><template #footer><el-button :disabled="saving" @click="updateConfig(true)">{{ tr("恢复默认") }}</el-button><el-button :disabled="saving" @click="configDialog=false">{{ tr("取消") }}</el-button><el-button type="primary" :loading="saving" @click="updateConfig()">{{ tr("保存") }}</el-button></template></el-dialog>
  <el-dialog v-model="partitionsDialog" :title="tr('增加 Topic 分区')" width="min(500px,94vw)" :close-on-click-modal="false"><el-form label-position="top" :disabled="saving"><el-form-item :label="tr('新的分区总数')"><el-input-number v-model="newPartitions" :min="partitions.length+1" :max="10000"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="partitionsDialog=false">{{ tr("取消") }}</el-button><el-button type="primary" :loading="saving" @click="increasePartitions">{{ tr("增加分区") }}</el-button></template></el-dialog>
 </section>
</template>
